with src as (select * from order_items where product_id is null and unit_price between 230 and 310 and quantity > 3), OrderItemsStats as (select case when unit_price >= 300 then 'high' when unit_price >= 120 then 'mid' else 'low' end as unit_price_bucket, round(avg(quantity), 2) as avg_quantity, count(distinct quantity) as unique_orders from src group by case when unit_price >= 300 then 'high' when unit_price >= 120 then 'mid' else 'low' end) select unit_price_bucket, avg_quantity, unique_orders from OrderItemsStats where unique_orders >= 5 order by avg_quantity desc, unit_price_bucket limit 1
